# Generate K_{5,5} edges
edges = []
for i in range(5):
    for j in range(5, 10):
        edges.append((i, j))
print("Edges:", edges)
print("Number of edges:", len(edges))

# Verify triangle-free
adj = {i: set() for i in range(10)}
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

def has_triangle():
    for u in range(10):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w > v and w in adj[u]:
                        return True
    return False
print("Has triangle:", has_triangle())

# Verify maximal: adding any non-edge creates a triangle
non_edges = []
for u in range(10):
    for v in range(u+1, 10):
        if v not in adj[u]:
            non_edges.append((u,v))
print("Non-edges:", non_edges)

def adding_creates_triangle(u,v):
    # check if u and v have a common neighbor
    for w in adj[u]:
        if w in adj[v]:
            return True
    return False

all_create = True
for u,v in non_edges:
    if not adding_creates_triangle(u,v):
        print(f"Adding ({u},{v}) does not create triangle")
        all_create = False
print("All non-edges create triangle:", all_create)
